"""100 distinct SQL templates. {f} is the scenario-filtered domain CTE.

The fixture uses common physical columns, with explicit domain semantics in
DOMAIN_SPECS. Templates differ in their actual relational computations.
"""
DOMAIN_SPECS = {
 'commerce': ('orders', ['paid','cancelled','pending'], ['electronics','food','home','fashion'], 'amount=gross order converted_value; quantity=items; adjustments=refunds'),
 'saas': ('invoices', ['active','cancelled','unpaid'], ['basic','pro','enterprise','trial'], 'amount=invoice converted_value; quantity=seats; adjustments=credits'),
 'marketing': ('touches', ['view','cart','purchase'], ['search','social','email','direct'], 'amount=conversion converted_value; entity_id=visitor; adjustments=invalidated conversions'),
 'finance': ('postings', ['posted','reversed','pending'], ['USD','EUR','CNY','GBP'], 'signed amount=ledger movement; adjustments=reconciliation corrections'),
 'inventory': ('movements', ['inbound','outbound','reserved'], ['north','south','east','west'], 'signed quantity=stock movement; amount=valuation; entity_id=SKU'),
 'telemetry': ('readings', ['ok','failed','missing'], ['temperature','pressure','voltage','humidity'], 'amount=sensor measurement; duration_ms=latency; entity_id=device'),
 'support': ('tickets', ['open','resolved','escalated'], ['billing','technical','account','general'], 'duration_ms=resolution duration; amount=service service_cost; entity_id=customer'),
 'workforce': ('attendance', ['present','absent','leave'], ['engineering','sales','ops','support'], 'amount=pay; quantity=hours; duration_ms=shift duration; entity_id=employee'),
 'supply': ('shipments', ['delivered','delayed','cancelled'], ['air','sea','road','rail'], 'amount=freight service_cost; quantity=delivered units; duration_ms=transit duration'),
 'experiments': ('outcomes', ['converted','exposed','excluded'], ['control','variant_a','variant_b','variant_c'], 'amount=outcome converted_value; quantity=engagement; entity_id=participant'),
}

# Each entry: English description, SQL, numeric comparison policy.
# Exact DECIMAL for monetary outputs; only explicit statistical outputs use
# relative/absolute tolerance (1e-8 / 1e-7).
TEMPLATES = {}
def add(domain, title, sql, approximate=False):
    TEMPLATES.setdefault(domain, []).append((title,sql,approximate))

# Commerce: refund fanout, star joins, cohorts, cumulative shares and rank.
add('commerce','Revenue by region and product',"SELECT d.region,f.category,COUNT(*),SUM(f.amount),SUM(f.quantity) FROM f JOIN d ON f.entity_id=d.entity_id WHERE f.state='paid' GROUP BY d.region,f.category ORDER BY d.region,f.category")
add('commerce','Refund-safe net revenue',"WITH a AS (SELECT fact_id,SUM(amount) r FROM a0 GROUP BY fact_id) SELECT COUNT(*),SUM(f.amount),SUM(COALESCE(a.r,0)),SUM(f.amount-COALESCE(a.r,0)) FROM f LEFT JOIN a ON f.fact_id=a.fact_id WHERE f.state='paid'")
add('commerce','Top products per region with deterministic ties',"WITH s AS (SELECT d.region,f.category,SUM(f.amount) revenue FROM f JOIN d ON f.entity_id=d.entity_id GROUP BY d.region,f.category),r AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY region ORDER BY revenue DESC,category) rn FROM s) SELECT * FROM r WHERE rn<=3 ORDER BY region,rn")
add('commerce','Daily revenue and seven-observation moving sum',"WITH s AS (SELECT CAST(event_time AS DATE) observation_date,SUM(amount) revenue FROM f WHERE state='paid' GROUP BY CAST(event_time AS DATE)) SELECT observation_date,revenue,SUM(revenue) OVER(ORDER BY observation_date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) FROM s ORDER BY observation_date")
add('commerce','Acquisition cohort active buyers',"SELECT YEAR(d.joined_at),MONTH(d.joined_at),YEAR(f.event_time),MONTH(f.event_time),COUNT(DISTINCT f.entity_id),SUM(f.amount) FROM f JOIN d ON f.entity_id=d.entity_id WHERE f.state='paid' GROUP BY 1,2,3,4 ORDER BY 1,2,3,4")
add('commerce','Repeat buyers and single-purchase buyers',"WITH s AS (SELECT entity_id,COUNT(*) n,SUM(amount) v FROM f WHERE state='paid' GROUP BY entity_id) SELECT SUM(CASE WHEN n=1 THEN 1 ELSE 0 END),SUM(CASE WHEN n>1 THEN 1 ELSE 0 END),SUM(CASE WHEN n>1 THEN v ELSE 0 END) FROM s")
add('commerce','Customer revenue cumulative concentration',"WITH s AS (SELECT entity_id,SUM(amount) v FROM f GROUP BY entity_id) SELECT entity_id,v,SUM(v) OVER(ORDER BY v DESC,entity_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW),SUM(v) OVER() FROM s ORDER BY v DESC,entity_id")
add('commerce','Distinct buyer-product-channel combinations',"SELECT COUNT(*) FROM (SELECT DISTINCT entity_id,category,channel FROM f) s")
add('commerce','Monthly revenue changes',"WITH s AS (SELECT YEAR(event_time) y,MONTH(event_time) m,SUM(amount) v FROM f WHERE state='paid' GROUP BY 1,2) SELECT y,m,v,LAG(v) OVER(ORDER BY y,m),v-LAG(v) OVER(ORDER BY y,m) FROM s ORDER BY y,m")
add('commerce','Orphan dimensions and cancelled order audit',"SELECT state,COUNT(*),SUM(amount) FROM f WHERE NOT EXISTS(SELECT 1 FROM d WHERE d.entity_id=f.entity_id) GROUP BY state ORDER BY state")

# Subscription billing: retention, lifecycle, expansion and invoice ageing.
add('saas','Monthly recurring revenue by plan',"SELECT YEAR(event_time),MONTH(event_time),category,COUNT(DISTINCT entity_id),SUM(amount),SUM(quantity) FROM f WHERE state='active' GROUP BY 1,2,3 ORDER BY 1,2,3")
add('saas','Latest account lifecycle and churn state',"WITH r AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY entity_id ORDER BY event_time DESC,fact_id DESC) rn FROM f) SELECT state,COUNT(*),SUM(amount) FROM r WHERE rn=1 GROUP BY state ORDER BY state")
add('saas','Account monthly expansion and contraction',"WITH s AS (SELECT entity_id,YEAR(event_time) y,MONTH(event_time) m,SUM(amount) v FROM f GROUP BY 1,2,3),r AS (SELECT *,LAG(v) OVER(PARTITION BY entity_id ORDER BY y,m) prior_v FROM s) SELECT entity_id,y,m,v,prior_v,CASE WHEN v>prior_v THEN 'expansion' WHEN v<prior_v THEN 'contraction' ELSE 'stable_or_first' END FROM r ORDER BY entity_id,y,m")
add('saas','Signup cohort retention counts',"SELECT d.segment,YEAR(d.joined_at),MONTH(d.joined_at),MONTH(f.event_time),COUNT(DISTINCT d.entity_id) FROM d LEFT JOIN f ON d.entity_id=f.entity_id AND f.state='active' GROUP BY 1,2,3,4 ORDER BY 1,2,3,COALESCE(MONTH(f.event_time),-1)")
add('saas','First and last invoice retention converted_value pair',"WITH r AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY entity_id ORDER BY event_time,fact_id) first_n,ROW_NUMBER() OVER(PARTITION BY entity_id ORDER BY event_time DESC,fact_id DESC) last_n FROM f) SELECT entity_id,SUM(CASE WHEN first_n=1 THEN amount ELSE 0 END),SUM(CASE WHEN last_n=1 THEN amount ELSE 0 END),COUNT(*) FROM r GROUP BY entity_id ORDER BY entity_id")
add('saas','Reactivated accounts after cancellation',"SELECT entity_id,COUNT(*) FROM f WHERE state='active' AND EXISTS(SELECT 1 FROM f old WHERE old.entity_id=f.entity_id AND old.state='cancelled' AND old.event_time<f.event_time) GROUP BY entity_id ORDER BY entity_id")
add('saas','Unpaid invoice ageing buckets',"SELECT CASE WHEN TIMESTAMPDIFF(DAY,event_time,CAST('2039-01-01' AS DATETIME))>90 THEN '90plus' WHEN TIMESTAMPDIFF(DAY,event_time,CAST('2039-01-01' AS DATETIME))>30 THEN '31to90' ELSE '0to30' END bucket,COUNT(*),SUM(amount) FROM f WHERE state='unpaid' GROUP BY 1 ORDER BY 1")
add('saas','Three-observation seat moving average',"WITH s AS (SELECT YEAR(event_time) y,MONTH(event_time) m,SUM(quantity) seats FROM f GROUP BY 1,2) SELECT y,m,seats,CAST(AVG(CAST(seats AS DECIMAL(24,6))) OVER(ORDER BY y,m ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS DECIMAL(24,6)) FROM s ORDER BY y,m",True)
add('saas','Plan converted_value deciles',"WITH r AS (SELECT fact_id,category,amount,NTILE(10) OVER(ORDER BY amount,fact_id) decile FROM f) SELECT decile,COUNT(*),MIN(amount),MAX(amount),SUM(amount) FROM r GROUP BY decile ORDER BY decile")
add('saas','Credits reconciled by account',"WITH a AS (SELECT fact_id,SUM(amount) credit FROM a0 GROUP BY fact_id) SELECT f.entity_id,SUM(f.amount),SUM(COALESCE(a.credit,0)),COUNT(a.fact_id) FROM f LEFT JOIN a ON f.fact_id=a.fact_id GROUP BY f.entity_id ORDER BY f.entity_id")

# Marketing: ordered funnels, attribution, de-duplication and event sequencing.
add('marketing','Strict ordered conversion funnel',"WITH s AS (SELECT entity_id,MIN(CASE WHEN state='view' THEN event_time END) v,MIN(CASE WHEN state='cart' THEN event_time END) c,MIN(CASE WHEN state='purchase' THEN event_time END) p FROM f GROUP BY entity_id) SELECT COUNT(*),SUM(CASE WHEN c>v THEN 1 ELSE 0 END),SUM(CASE WHEN p>c AND c>v THEN 1 ELSE 0 END) FROM s")
add('marketing','Last-touch channel attribution',"WITH r AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY entity_id ORDER BY event_time DESC,fact_id DESC) rn FROM f) SELECT channel,COUNT(*),SUM(amount) FROM r WHERE rn=1 GROUP BY channel ORDER BY COALESCE(channel,''),CASE WHEN channel IS NULL THEN 0 ELSE 1 END")
add('marketing','Visitor channel spread and conversion converted_value',"WITH s AS (SELECT entity_id,COUNT(DISTINCT channel) channels,SUM(CASE WHEN state='purchase' THEN amount ELSE 0 END) converted_value FROM f GROUP BY entity_id) SELECT channels,COUNT(*),SUM(converted_value) FROM s GROUP BY channels ORDER BY channels")
add('marketing','Duplicate event fingerprint audit',"SELECT entity_id,event_time,state,COUNT(*) n FROM f GROUP BY entity_id,event_time,state HAVING COUNT(*)>1 ORDER BY entity_id,event_time,state")
add('marketing','Adjacent event transition paths',"WITH r AS (SELECT entity_id,fact_id,state,LAG(state) OVER(PARTITION BY entity_id ORDER BY event_time,fact_id) previous_state FROM f) SELECT previous_state,state,COUNT(*) FROM r WHERE previous_state IS NOT NULL GROUP BY previous_state,state ORDER BY previous_state,state")
add('marketing','Idle gaps between visitor events',"WITH r AS (SELECT entity_id,fact_id,event_time,LAG(event_time) OVER(PARTITION BY entity_id ORDER BY event_time,fact_id) previous_time FROM f) SELECT entity_id,COUNT(*),MAX(TIMESTAMPDIFF(SECOND,previous_time,event_time)) FROM r WHERE previous_time IS NOT NULL GROUP BY entity_id ORDER BY entity_id")
add('marketing','First-touch acquisition channel',"WITH r AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY entity_id ORDER BY event_time,fact_id) rn FROM f) SELECT COALESCE(channel,'unknown') ch,COUNT(*) FROM r WHERE rn=1 GROUP BY COALESCE(channel,'unknown') ORDER BY ch")
add('marketing','Channels with views and no conversions',"SELECT DISTINCT channel FROM f x WHERE x.channel IS NOT NULL AND x.state='view' AND NOT EXISTS(SELECT 1 FROM f y WHERE y.channel=x.channel AND y.state='purchase') ORDER BY channel")
add('marketing','Seven-observation_date distinct visitor lookback',"WITH days AS (SELECT DISTINCT CAST(event_time AS DATE) observation_date FROM f) SELECT observation_date,(SELECT COUNT(DISTINCT entity_id) FROM f WHERE CAST(event_time AS DATE)<=days.observation_date AND TIMESTAMPDIFF(DAY,event_time,CAST(days.observation_date AS DATETIME)) BETWEEN 0 AND 6) FROM days ORDER BY observation_date")
add('marketing','Null versus empty attribution strings',"SELECT COUNT(*),COUNT(channel),COUNT(DISTINCT channel),SUM(CASE WHEN channel IS NULL THEN 1 ELSE 0 END),SUM(CASE WHEN channel='' THEN 1 ELSE 0 END),SUM(CASE WHEN note LIKE '%中文%' THEN 1 ELSE 0 END) FROM f")

# Finance: exact signed DECIMAL, balances, reconciliation and effective dating.
add('finance','Running account balances',"SELECT entity_id,fact_id,event_time,amount,SUM(amount) OVER(PARTITION BY entity_id ORDER BY event_time,fact_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) balance FROM f WHERE state='posted' ORDER BY entity_id,event_time,fact_id")
add('finance','Trial balance credit debit net',"SELECT category,SUM(CASE WHEN amount>=0 THEN amount ELSE 0 END) debit,SUM(CASE WHEN amount<0 THEN -amount ELSE 0 END) credit,SUM(amount) net FROM f GROUP BY category ORDER BY category")
add('finance','FX conversion using monthly rate dimension',"SELECT f.category,YEAR(f.event_time),MONTH(f.event_time),SUM(f.amount),SUM(CAST(f.amount*x.rate AS DECIMAL(30,6))) FROM f JOIN x ON x.currency=f.category AND x.year=YEAR(f.event_time) AND x.month=MONTH(f.event_time) GROUP BY 1,2,3 ORDER BY 1,2,3")
add('finance','Exact cancellation pairs by account',"SELECT entity_id,COUNT(*),SUM(amount),MIN(amount),MAX(amount) FROM f GROUP BY entity_id HAVING SUM(amount)=0 ORDER BY entity_id")
add('finance','Daily posted versus pending settlement',"SELECT CAST(event_time AS DATE) observation_date,SUM(CASE WHEN state='posted' THEN amount ELSE 0 END),SUM(CASE WHEN state='pending' THEN amount ELSE 0 END),COUNT(*) FROM f GROUP BY 1 ORDER BY 1")
add('finance','Reconciliation adjustment anti-join',"SELECT fact_id,entity_id,amount FROM f WHERE NOT EXISTS(SELECT 1 FROM a0 WHERE a0.fact_id=f.fact_id) AND state='posted' ORDER BY fact_id")
add('finance','Monthly closing last posting',"WITH r AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY entity_id,YEAR(event_time),MONTH(event_time) ORDER BY event_time DESC,fact_id DESC) rn FROM f) SELECT entity_id,YEAR(event_time),MONTH(event_time),fact_id,amount FROM r WHERE rn=1 ORDER BY 1,2,3")
add('finance','Effective-dated account segment reconciliation',"SELECT h.segment,COUNT(*),SUM(f.amount) FROM f JOIN h ON f.entity_id=h.entity_id AND f.event_time>=h.valid_from AND f.event_time<h.valid_to GROUP BY h.segment ORDER BY h.segment")
add('finance','Negative cumulative balance alerts',"WITH r AS (SELECT entity_id,fact_id,SUM(amount) OVER(PARTITION BY entity_id ORDER BY event_time,fact_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) balance FROM f) SELECT entity_id,COUNT(*),MIN(balance) FROM r WHERE balance<0 GROUP BY entity_id ORDER BY entity_id")
add('finance','Repeated CTE debit balance comparison',"WITH s AS (SELECT entity_id,SUM(amount) v FROM f GROUP BY entity_id) SELECT COUNT(*),SUM(a.v),SUM(b.v),SUM(a.v-b.v) FROM s a JOIN s b ON a.entity_id=b.entity_id")

# Inventory: signed units, stockouts, valuation and inactive catalog items.
add('inventory','Warehouse stock and valuation',"SELECT category,entity_id,SUM(quantity),SUM(amount) FROM f GROUP BY category,entity_id ORDER BY category,entity_id")
add('inventory','Running stock position below zero',"WITH r AS (SELECT entity_id,fact_id,event_time,SUM(quantity) OVER(PARTITION BY entity_id ORDER BY event_time,fact_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) stock FROM f) SELECT entity_id,COUNT(*),MIN(stock) FROM r WHERE stock<0 GROUP BY entity_id ORDER BY entity_id")
add('inventory','Value and unit denominator with zero-stock safety',"WITH s AS (SELECT entity_id,SUM(amount) v,SUM(quantity) q FROM f GROUP BY entity_id) SELECT entity_id,v,q,CASE WHEN q=0 THEN NULL ELSE CAST(CAST(v AS DECIMAL(38,12))/q AS DECIMAL(24,6)) END FROM s ORDER BY entity_id")
add('inventory','Age of last inbound movement',"SELECT entity_id,MAX(event_time),TIMESTAMPDIFF(DAY,MAX(event_time),CAST('2039-01-01' AS DATETIME)) FROM f WHERE state='inbound' GROUP BY entity_id ORDER BY entity_id")
add('inventory','Entities without inbound supply',"SELECT entity_id,COUNT(*),SUM(quantity) FROM f z WHERE NOT EXISTS(SELECT 1 FROM f y WHERE y.entity_id=z.entity_id AND y.state='inbound') GROUP BY entity_id ORDER BY entity_id")
add('inventory','Rolling replenishment quantity',"SELECT entity_id,fact_id,quantity,SUM(quantity) OVER(PARTITION BY entity_id ORDER BY event_time,fact_id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) FROM f WHERE state='inbound' ORDER BY entity_id,event_time,fact_id")
add('inventory','Latest movement per warehouse SKU',"WITH r AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY category,entity_id ORDER BY event_time DESC,fact_id DESC) rn FROM f) SELECT category,entity_id,fact_id,quantity,state FROM r WHERE rn=1 ORDER BY category,entity_id")
add('inventory','Catalog items with no movements',"SELECT d.entity_id,d.region FROM d WHERE NOT EXISTS(SELECT 1 FROM f WHERE f.entity_id=d.entity_id) ORDER BY d.entity_id")
add('inventory','Movement quantity first difference',"SELECT entity_id,fact_id,quantity,quantity-LAG(quantity) OVER(PARTITION BY entity_id ORDER BY event_time,fact_id) FROM f ORDER BY entity_id,event_time,fact_id")
add('inventory','Warehouse conditional pivot',"SELECT entity_id,SUM(CASE WHEN category='north' THEN quantity ELSE 0 END),SUM(CASE WHEN category='south' THEN quantity ELSE 0 END),SUM(CASE WHEN category IN('east','west') THEN quantity ELSE 0 END) FROM f GROUP BY entity_id ORDER BY entity_id")

# Telemetry: statistical values have explicit tolerances, timestamps remain exact.
add('telemetry','Sensor distribution and population variance',"SELECT entity_id,COUNT(*),AVG(CAST(amount AS DOUBLE)),VAR_POP(CAST(amount AS DOUBLE)),MIN(amount),MAX(amount) FROM f GROUP BY entity_id ORDER BY entity_id",True)
add('telemetry','Three-sample rolling sensor statistics',"SELECT entity_id,fact_id,AVG(CAST(amount AS DOUBLE)) OVER(PARTITION BY entity_id ORDER BY event_time,fact_id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW),MIN(amount) OVER(PARTITION BY entity_id ORDER BY event_time,fact_id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) FROM f ORDER BY entity_id,event_time,fact_id",True)
add('telemetry','Sensor inter-arrival gaps',"WITH r AS (SELECT entity_id,fact_id,event_time,LAG(event_time) OVER(PARTITION BY entity_id ORDER BY event_time,fact_id) prev FROM f) SELECT entity_id,COUNT(prev),MIN(TIMESTAMPDIFF(SECOND,prev,event_time)),MAX(TIMESTAMPDIFF(SECOND,prev,event_time)) FROM r GROUP BY entity_id ORDER BY entity_id")
add('telemetry','Latest device health snapshot',"WITH r AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY entity_id ORDER BY event_time DESC,fact_id DESC) rn FROM f) SELECT entity_id,state,amount,duration_ms,note FROM r WHERE rn=1 ORDER BY entity_id")
add('telemetry','Hourly sensor bucket counts',"SELECT CAST(event_time AS DATE),HOUR(event_time),category,COUNT(*),SUM(amount) FROM f GROUP BY 1,2,3 ORDER BY 1,2,3")
add('telemetry','Neighbor values for interpolation',"SELECT entity_id,fact_id,LAG(amount) OVER(PARTITION BY entity_id ORDER BY event_time,fact_id),amount,LEAD(amount) OVER(PARTITION BY entity_id ORDER BY event_time,fact_id) FROM f ORDER BY entity_id,event_time,fact_id")
add('telemetry','Uptime observations and missing latency',"SELECT entity_id,SUM(CASE WHEN state='ok' THEN 1 ELSE 0 END),SUM(CASE WHEN state='failed' THEN 1 ELSE 0 END),COUNT(*),COUNT(duration_ms),SUM(duration_ms) FROM f GROUP BY entity_id ORDER BY entity_id")
add('telemetry','All tied sensor maximum points',"WITH s AS (SELECT entity_id,MAX(amount) peak FROM f GROUP BY entity_id) SELECT f.entity_id,f.fact_id,f.amount FROM f JOIN s ON f.entity_id=s.entity_id AND f.amount=s.peak ORDER BY f.entity_id,f.fact_id")
add('telemetry','Consecutive device-state run segments',"WITH p AS (SELECT *,LAG(state) OVER(PARTITION BY entity_id ORDER BY event_time,fact_id) prev FROM f),r AS (SELECT *,SUM(CASE WHEN prev=state THEN 0 ELSE 1 END) OVER(PARTITION BY entity_id ORDER BY event_time,fact_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) run_n FROM p) SELECT entity_id,run_n,state,COUNT(*),MIN(event_time),MAX(event_time) FROM r GROUP BY entity_id,run_n,state ORDER BY entity_id,run_n,state")
add('telemetry','Deviation from device mean',"WITH s AS (SELECT entity_id,AVG(CAST(amount AS DOUBLE)) mean_v FROM f GROUP BY entity_id) SELECT f.entity_id,COUNT(*) FROM f JOIN s ON f.entity_id=s.entity_id WHERE CAST(f.amount AS DOUBLE)>s.mean_v GROUP BY f.entity_id ORDER BY f.entity_id")

# Customer service: SLA, rankings, queue age and escalation sequence.
add('support','SLA breaches by queue',"SELECT category,COUNT(*),COUNT(duration_ms),SUM(CASE WHEN duration_ms>86400000 THEN 1 ELSE 0 END),MAX(duration_ms) FROM f WHERE state='resolved' GROUP BY category ORDER BY category")
add('support','Current backlog region and queue',"SELECT d.region,f.category,COUNT(*),SUM(f.amount) FROM f LEFT JOIN d ON f.entity_id=d.entity_id WHERE f.state='open' GROUP BY d.region,f.category ORDER BY COALESCE(d.region,''),f.category")
add('support','Open ticket fixed-cutoff age',"SELECT fact_id,entity_id,TIMESTAMPDIFF(DAY,event_time,CAST('2039-01-01' AS DATETIME)) age FROM f WHERE state='open' ORDER BY age DESC,fact_id")
add('support','Resolution latency cumulative distribution',"SELECT fact_id,duration_ms,CUME_DIST() OVER(ORDER BY COALESCE(duration_ms,-1),fact_id) FROM f WHERE state='resolved' ORDER BY COALESCE(duration_ms,-1),fact_id",True)
add('support','Customer-cohort SLA breach counts',"SELECT d.segment,YEAR(d.joined_at),COUNT(*),SUM(CASE WHEN f.duration_ms>86400000 THEN 1 ELSE 0 END) FROM f JOIN d ON f.entity_id=d.entity_id GROUP BY 1,2 ORDER BY 1,2")
add('support','Cumulative resolved ticket count',"WITH s AS (SELECT CAST(event_time AS DATE) observation_date,COUNT(*) n FROM f WHERE state='resolved' GROUP BY 1) SELECT observation_date,n,SUM(n) OVER(ORDER BY observation_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) FROM s ORDER BY observation_date")
add('support','Tickets above customer average duration',"SELECT fact_id,entity_id,duration_ms FROM f WHERE duration_ms>(SELECT AVG(z.duration_ms) FROM f z WHERE z.entity_id=f.entity_id) ORDER BY fact_id")
add('support','Customer service workload dense ranks',"WITH s AS (SELECT entity_id,COUNT(*) n,SUM(amount) service_cost FROM f GROUP BY entity_id) SELECT *,DENSE_RANK() OVER(ORDER BY n DESC) r FROM s ORDER BY n DESC,entity_id")
add('support','Escalation next state audit',"WITH r AS (SELECT fact_id,entity_id,state,LEAD(state) OVER(PARTITION BY entity_id ORDER BY event_time,fact_id) next_state FROM f) SELECT fact_id,entity_id,next_state FROM r WHERE state='escalated' ORDER BY fact_id")
add('support','Latency null and zero boundary audit',"SELECT COUNT(*),COUNT(duration_ms),SUM(CASE WHEN duration_ms=0 THEN 1 ELSE 0 END),SUM(CASE WHEN duration_ms IS NULL THEN 1 ELSE 0 END),MIN(duration_ms),MAX(duration_ms) FROM f")

# Workforce: attendance gaps, payroll, consecutive days and job history.
add('workforce','Employee attendance gaps in days',"WITH r AS (SELECT entity_id,fact_id,event_time,LAG(event_time) OVER(PARTITION BY entity_id ORDER BY event_time,fact_id) prev FROM f WHERE state='present') SELECT entity_id,COUNT(*),MAX(TIMESTAMPDIFF(DAY,prev,event_time)) FROM r GROUP BY entity_id ORDER BY entity_id")
add('workforce','Payroll credits without adjustment fanout',"WITH a AS (SELECT fact_id,SUM(amount) extra FROM a0 GROUP BY fact_id) SELECT f.entity_id,SUM(f.amount+COALESCE(a.extra,0)),SUM(f.quantity) FROM f LEFT JOIN a ON f.fact_id=a.fact_id GROUP BY f.entity_id ORDER BY f.entity_id")
add('workforce','Employees absent from attendance records',"SELECT d.entity_id,d.segment FROM d WHERE NOT EXISTS(SELECT 1 FROM f WHERE f.entity_id=d.entity_id AND f.state='present') ORDER BY d.entity_id")
add('workforce','Overtime hours by department',"SELECT category,SUM(CASE WHEN quantity>8 THEN quantity-8 ELSE 0 END),SUM(CASE WHEN duration_ms>28800000 THEN duration_ms-28800000 ELSE 0 END),COUNT(*) FROM f WHERE state='present' GROUP BY category ORDER BY category")
add('workforce','Department payroll employee ranks',"WITH s AS (SELECT category,entity_id,SUM(amount) pay FROM f GROUP BY category,entity_id) SELECT *,RANK() OVER(PARTITION BY category ORDER BY pay DESC) rank_n FROM s ORDER BY category,pay DESC,entity_id")
add('workforce','Consecutive attendance observation_date islands',"WITH days AS (SELECT DISTINCT entity_id,CAST(event_time AS DATE) observation_date FROM f WHERE state='present'),r AS (SELECT entity_id,observation_date,TIMESTAMPDIFF(DAY,CAST('1970-01-01' AS DATETIME),CAST(observation_date AS DATETIME))-ROW_NUMBER() OVER(PARTITION BY entity_id ORDER BY observation_date) island FROM days) SELECT entity_id,island,COUNT(*),MIN(observation_date),MAX(observation_date) FROM r GROUP BY entity_id,island ORDER BY entity_id,island")
add('workforce','Region absence and leave pivot',"SELECT d.region,SUM(CASE WHEN f.state='absent' THEN 1 ELSE 0 END),SUM(CASE WHEN f.state='leave' THEN 1 ELSE 0 END),SUM(CASE WHEN f.state='present' THEN 1 ELSE 0 END) FROM d LEFT JOIN f ON d.entity_id=f.entity_id GROUP BY d.region ORDER BY d.region")
add('workforce','Effective job segment payroll',"SELECT h.segment,f.category,COUNT(*),SUM(f.amount) FROM f JOIN h ON f.entity_id=h.entity_id AND f.event_time>=h.valid_from AND f.event_time<h.valid_to GROUP BY h.segment,f.category ORDER BY h.segment,f.category")
add('workforce','Pay above department mean',"WITH s AS (SELECT category,COUNT(*) n,SUM(amount) total_pay FROM f GROUP BY category) SELECT f.fact_id,f.category,f.amount FROM f JOIN s ON f.category=s.category WHERE f.amount*s.n>s.total_pay ORDER BY f.fact_id")
add('workforce','Employee monthly attendance count changes',"WITH s AS (SELECT entity_id,YEAR(event_time) y,MONTH(event_time) m,COUNT(*) n FROM f GROUP BY 1,2,3) SELECT *,n-LAG(n) OVER(PARTITION BY entity_id ORDER BY y,m) FROM s ORDER BY entity_id,y,m")

# Supply chain: fill rates, delivery streaks, lead-time and supplier cohorts.
add('supply','Transport mode delivered units and costs',"SELECT category,SUM(CASE WHEN state='delivered' THEN quantity ELSE 0 END),SUM(quantity),SUM(amount),COUNT(*) FROM f GROUP BY category ORDER BY category")
add('supply','Supplier delivery latency distribution',"SELECT entity_id,COUNT(duration_ms),MIN(duration_ms),MAX(duration_ms),CAST(AVG(duration_ms) AS DECIMAL(24,6)) FROM f WHERE state='delivered' GROUP BY entity_id ORDER BY entity_id",True)
add('supply','Region delayed shipment exposure',"SELECT COALESCE(d.region,'unknown'),COUNT(*),SUM(f.amount),SUM(f.quantity) FROM f LEFT JOIN d ON f.entity_id=d.entity_id WHERE f.state='delayed' GROUP BY 1 ORDER BY 1")
add('supply','First supplier shipment and repeat count',"SELECT entity_id,MIN(event_time),MAX(event_time),COUNT(*),COUNT(DISTINCT category) FROM f GROUP BY entity_id ORDER BY entity_id")
add('supply','Rolling delivered units supplier window',"SELECT entity_id,fact_id,SUM(CASE WHEN state='delivered' THEN quantity ELSE 0 END) OVER(PARTITION BY entity_id ORDER BY event_time,fact_id ROWS BETWEEN 4 PRECEDING AND CURRENT ROW) FROM f ORDER BY entity_id,event_time,fact_id")
add('supply','Cancelled shipment refund reconciliation',"WITH a AS (SELECT fact_id,SUM(amount) refund FROM a0 GROUP BY fact_id) SELECT f.fact_id,f.amount,COALESCE(a.refund,0),f.amount-COALESCE(a.refund,0) FROM f LEFT JOIN a ON f.fact_id=a.fact_id WHERE f.state='cancelled' ORDER BY f.fact_id")
add('supply','Suppliers with delays and no successful delivery',"SELECT entity_id,COUNT(*) FROM f a WHERE a.state='delayed' AND NOT EXISTS(SELECT 1 FROM f b WHERE b.entity_id=a.entity_id AND b.state='delivered') GROUP BY entity_id ORDER BY entity_id")
add('supply','Transport service_cost quartile boundaries',"WITH r AS (SELECT fact_id,amount,NTILE(4) OVER(ORDER BY amount,fact_id) quartile FROM f) SELECT quartile,COUNT(*),MIN(amount),MAX(amount) FROM r GROUP BY quartile ORDER BY quartile")
add('supply','Latest supplier channel with missing strings',"WITH r AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY entity_id ORDER BY event_time DESC,fact_id DESC) rn FROM f) SELECT entity_id,COALESCE(channel,'unassigned'),note,state FROM r WHERE rn=1 ORDER BY entity_id")
add('supply','Monthly delivery status full pivot',"SELECT YEAR(event_time),MONTH(event_time),SUM(CASE WHEN state='delivered' THEN 1 ELSE 0 END),SUM(CASE WHEN state='delayed' THEN 1 ELSE 0 END),SUM(CASE WHEN state='cancelled' THEN 1 ELSE 0 END) FROM f GROUP BY 1,2 ORDER BY 1,2")

# Experiment analysis: unit of analysis, repeated exposure, balance and leakage.
add('experiments','Participant-level deduplicated outcomes',"WITH s AS (SELECT category,entity_id,MAX(CASE WHEN state='converted' THEN 1 ELSE 0 END) converted,SUM(amount) revenue FROM f GROUP BY category,entity_id) SELECT category,COUNT(*),SUM(converted),SUM(revenue) FROM s GROUP BY category ORDER BY category")
add('experiments','Cross-arm contamination audit',"SELECT entity_id,COUNT(DISTINCT category) arms FROM f GROUP BY entity_id HAVING COUNT(DISTINCT category)>1 ORDER BY entity_id")
add('experiments','First exposure assignment intention to treat',"WITH r AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY entity_id ORDER BY event_time,fact_id) rn FROM f) SELECT category,COUNT(*),SUM(CASE WHEN state='converted' THEN 1 ELSE 0 END) FROM r WHERE rn=1 GROUP BY category ORDER BY category")
add('experiments','Sample ratio and segment balance counts',"SELECT f.category,d.segment,COUNT(*),COUNT(DISTINCT f.entity_id) FROM f LEFT JOIN d ON f.entity_id=d.entity_id GROUP BY f.category,d.segment ORDER BY f.category,COALESCE(d.segment,'')")
add('experiments','Outcome mean variance for uncertainty',"SELECT category,COUNT(*),AVG(CAST(amount AS DOUBLE)),VAR_POP(CAST(amount AS DOUBLE)),SUM(amount) FROM f WHERE state<>'excluded' GROUP BY category ORDER BY category",True)
add('experiments','Pre versus post reference date metrics',"SELECT category,SUM(CASE WHEN event_time<CAST('2025-07-01' AS DATETIME) THEN amount ELSE 0 END),SUM(CASE WHEN event_time>=CAST('2025-07-01' AS DATETIME) THEN amount ELSE 0 END),COUNT(*) FROM f GROUP BY category ORDER BY category")
add('experiments','Daily cumulative exposure by arm',"WITH s AS (SELECT category,CAST(event_time AS DATE) observation_date,COUNT(*) n FROM f GROUP BY 1,2) SELECT category,observation_date,n,SUM(n) OVER(PARTITION BY category ORDER BY observation_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) FROM s ORDER BY category,observation_date")
add('experiments','Participants with no conversion or excluded observations',"SELECT entity_id,COUNT(*) FROM f a WHERE NOT EXISTS(SELECT 1 FROM f b WHERE b.entity_id=a.entity_id AND b.state IN('converted','excluded')) GROUP BY entity_id ORDER BY entity_id")
add('experiments','Outcome empirical percentile ranks',"SELECT category,fact_id,amount,PERCENT_RANK() OVER(PARTITION BY category ORDER BY amount,fact_id) FROM f ORDER BY category,amount,fact_id",True)
add('experiments','Repeated exposure UNION ALL identity',"SELECT COUNT(*),COUNT(DISTINCT entity_id),SUM(amount) FROM (SELECT entity_id,amount FROM f UNION ALL SELECT entity_id,amount FROM f) u")

assert len(TEMPLATES)==10 and all(len(v)==10 for v in TEMPLATES.values())
assert len({sql for cases in TEMPLATES.values() for _,sql,_ in cases})==100
